{
  "root_cause": "The datepicker component prevents the default action of the Tab key when the calendar is shown, preventing focus from moving to the next field in the form.",
  "repair_strategy": "Add a keydown listener on the datepicker input that hides the calendar when the Tab key is pressed (if the calendar is shown) and allows the Tab event to proceed by not preventing its default action.",
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected declare _element: HTMLElement & { value: string }
  protected declare _config: DatepickerConfig
  protected declare _calendar: Calendar | null
  protected declare _isShown: boolean
  protected declare _isInput: boolean
  protected declare _isInline: boolean
  protected declare _boundInput: HTMLInputElement | null
  protected declare _positionElement: HTMLElement
  protected declare _displayElement: HTMLElement | false | null
  protected declare _themeObserver: MutationObserver | null
  protected declare _themeAncestor: Element | null | undefined
  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void",
      "after": "  protected declare _element: HTMLElement & { value: string }
  protected declare _config: DatepickerConfig
  protected declare _calendar: Calendar | null
  protected declare _isShown: boolean
  protected declare _isInput: boolean
  protected declare _isInline: boolean
  protected declare _boundInput: HTMLInputElement | null
  protected declare _positionElement: HTMLElement
  protected declare _displayElement: HTMLElement | false | null
  protected declare _themeObserver: MutationObserver | null
  protected declare _themeAncestor: Element | null | undefined
  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void
  protected declare _onTabKey: (event: KeyboardEvent) => void"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    // Watch for theme changes on ancestor elements (for live theme switching)
    this._setupThemeObserver()

    this._setupDismiss()

    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
  }",
      "after": "    // Watch for theme changes on ancestor elements (for live theme switching)
    this._setupThemeObserver()

    this._setupDismiss()

    // Handle Tab key to hide datepicker and allow focus to move
    this._onTabKey = (event: KeyboardEvent) => {
      if (event.key === 'Tab' && this._isShown) {
        this.hide()
      }
    }
    EventHandler.on(this._element, 'keydown', this._onTabKey)

    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()",
      "after": "    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._onTabKey) {
      EventHandler.off(this._element, 'keydown', this._onTabKey)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()"
    }
  ],
  "expected_accessibility_effect": "Pressing Tab from the departure date field will move focus to the passengers field, allowing seamless keyboard navigation through the form as expected.",
  "functional_risks": [
    "Hiding the calendar on Tab might interfere with users who expect to use Tab for navigation within the calendar (though the calendar primarily uses arrow keys for navigation).",
    "If the calendar hide operation is asynchronous, there could be a timing issue where the calendar remains visible briefly when focus moves, but the hide is triggered synchronously in the keydown handler.",
    "Users who rely on the calendar remaining open for multiple date selections (in multiple selection modes) might find it closes prematurely when pressing Tab, but this aligns with common datepicker behavior where Tab exits the widget."
  ],
  "verification_requirements": [
    "After the change, pressing Tab from the departure date field moves focus to the passengers field.",
    "The datepicker calendar closes when Tab is pressed from the departure date field.",
    "The value of the departure date field remains unchanged when Tab is pressed unless a date was selected via click or Enter.",
    "Other keyboard interactions with the datepicker (arrow keys, Enter, Escape) continue to function as expected.",
    "The calendar still opens correctly when the departure date field receives focus.",
    "Inline datepickers (if any) are unaffected by this change."
  ]
}
